with p.open('a') as f:f.write('''
const resilienceNote=t=>$('resilienceStatus').textContent=t;
$('downloadAll').onclick=async()=>{if(busy)return;busy=true;render();try{await refresh();if(!workerReady||!navigator.onLine){resilienceNote('Cần kết nối để tải những game còn thiếu.');return}const failed=[];for(const g of released){if(states[g.id])continue;try{await rpc(details[g.id]?.needsRepair?'REPAIR':'INSTALL',g.id);await refresh()}catch{failed.push(g.title)}}resilienceNote(failed.length?'Chưa tải được: '+failed.join(', '):'Tất cả game hiện có đã sẵn sàng offline.')}finally{busy=false;render()}};
$('persistStorage').onclick=async()=>{try{if(!navigator.storage?.persist)throw Error('unsupported');const ok=await navigator.storage.persist();resilienceNote(ok?'Trình duyệt đã cấp lưu trữ bền vững. Vẫn cần sao lưu bên ngoài.':'Chưa được cấp lưu trữ bền vững; hãy xuất bản lưu.')}catch{resilienceNote('Thiết bị không hỗ trợ yêu cầu lưu trữ bền vững. Hãy xuất bản lưu.')}};
const allowedSaves=new Set(released.flatMap(g=>g.save.keys));
if(['localhost','127.0.0.1','[::1]'].includes(location.hostname))document.querySelector('.resilience-actions a').hidden=true;
function collectSaves(){const saves={};for(const k of allowedSaves){const v=localStorage.getItem(k);if(v!==null)saves[k]=v}return {format:'xi-game-saves-v1',saves}}
function validateSaves(data){if(data?.format!=='xi-game-saves-v1'||!data.saves||typeof data.saves!=='object'||Array.isArray(data.saves))throw Error('Tệp bản lưu không hợp lệ.');const entries=Object.entries(data.saves);if(!entries.length||entries.some(([k,v])=>!allowedSaves.has(k)||typeof v!=='string'||v.length>2000000))throw Error('Tệp có dữ liệu không hợp lệ.');for(const [k,v] of entries){let parsed;try{parsed=JSON.parse(v)}catch{throw Error('Bản lưu không phải JSON hợp lệ: '+k)}if(k.endsWith(':best')?typeof parsed!=='number'||!Number.isFinite(parsed)||parsed<0:k.endsWith(':sound')?typeof parsed!=='boolean':!parsed||typeof parsed!=='object'||Array.isArray(parsed))throw Error('Dữ liệu bản lưu không đúng kiểu: '+k)}return entries}
$('exportSaves').onclick=()=>{try{const data=collectSaves();if(!Object.keys(data.saves).length){resilienceNote('Chưa có tiến trình để xuất.');return}const u=URL.createObjectURL(new Blob([JSON.stringify(data)],{type:'application/json'}));const a=e('a');a.href=u;a.download='Xi-Universe-saves-'+new Date().toISOString().slice(0,10)+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),30000);resilienceNote('Đã yêu cầu tải bản lưu. Kiểm tra thư mục tải xuống.')}catch{resilienceNote('Không thể xuất bản lưu.')}};
$('importSavesButton').onclick=()=>$('importSaves').click();
$('importSaves').onchange=async ev=>{const file=ev.target.files?.[0];ev.target.value='';if(!file)return;try{if(file.size>10000000)throw Error('Tệp quá lớn.');const entries=validateSaves(JSON.parse(await file.text()));if(!confirm('Nhập '+entries.length+' mục bản lưu? Các mục trùng sẽ bị ghi đè. Hãy xuất bản lưu hiện tại trước.'))return;const previous=entries.map(([k])=>[k,localStorage.getItem(k)]);try{for(const [k,v] of entries)localStorage.setItem(k,v)}catch(err){for(const [k,v] of previous){try{v===null?localStorage.removeItem(k):localStorage.setItem(k,v)}catch{}}throw err}resilienceNote('Đã nhập bản lưu. Mở lại trò chơi để sử dụng.')}catch(err){resilienceNote('Không thể nhập bản lưu: '+err.message)}};
''')
